        "<strong>TCP Half-Open Scan (SYN Scan):</strong> SYN 전송 -> 서버가 SYN+ACK 응답 시 포트 열림(Open) 판단 후 즉시 RST 전송하여 연결 강제 종료. 완전한 세션이 수립되지 않아 서버에 로그가 남지 않는 대표적 스텔스 스캔.",
