        "• <code>Null Scan</code>: 모든 플래그를 0(비트 없음)으로 전송.",
        "• <code>Xmas Scan</code>: FIN, PSH, URG 플래그를 모두 1로 세팅하여 전송 (크리스마스 트리처럼 불이 켜짐).",
