        "<strong>사후 조치:</strong> 침입 경로(IOC) 분석 → 취약점 패치 → 계정·권한 재설정 → 재발방지 대책 문서화. 백업은 반드시 <strong>복구 모의훈련</strong>까지 수행해야 실효가 있다."
