        "<strong>전자봉투:</strong> 대용량 문서는 속도가 빠른 <strong>대칭키(세션키)</strong>로 암호화하고, 그 세션키만 수신자의 <strong>공개키</strong>로 암호화해 함께 보낸다. 하이브리드 방식으로 기밀성과 성능을 동시에 확보하며, 세션키는 매 건 새로 생성한다.",
