        "<strong>감점 회피:</strong> '철저히 관리한다' 같은 선언적 표현 대신 <strong>주체·주기·산출물</strong>을 명시한다(예: '보안담당자는 내부 관리계획에 정한 주기(예: 월 1회)로 접속기록을 점검하고 결과를 CISO에 보고한다').",
