        "<strong>레지스트리·정책:</strong> <code>AlwaysInstallElevated=0</code>, <code>RestrictAnonymous=1</code>, 자동 로그온 비활성, 화면 보호기 잠금(스크린세이버 암호), LM 해시 저장 차단(<code>NoLMHash=1</code>), <code>secedit /export</code>로 정책 백업.",
