        "<strong>무결성:</strong> 원본·사본 해시 동시 기록(<code>sha256sum</code>), 해시 목록을 증거와 함께 보관, 분석은 사본으로만 수행, 연계보관성 대장에 취급자·일시·장소를 기록한다.",
