        "<strong>안티포렌식 대응:</strong> 타임스탬프 불일치(<code>stat</code>의 mtime vs ctime), 로그 공백, 대량 삭제 흔적, 암호화 볼륨, 스테가노그래피 의심 파일. 여러 아티팩트를 교차 검증해 위조를 판별한다.",
